import{_ as t}from"./chunks/Audio.COine8Wh.js";import{c as n,o as s,j as i,G as r,ae as a,a as o}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"Restoring Gold Standard Science","description":"","frontmatter":{"legisId":"2025-05-23-restoring-gold-standard-science","title":"Restoring Gold Standard Science","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/restoring-gold-standard-science/","publishDate":"2025-05-23T16:56:55-04:00","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Restoring Gold Standard Science\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-05-23-restoring-gold-standard-science\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Restoring Gold Standard Science\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-05-23-restoring-gold-standard-science\\",\\"datePublished\\":\\"2025-05-23T16:56:55-04:00\\",\\"dateModified\\":1768094639000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-05-23-restoring-gold-standard-science\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-05-23-restoring-gold-standard-science.md","filePath":"executive-orders/2025-05-23-restoring-gold-standard-science.md","lastUpdated":1768094639000}'),l={name:"executive-orders/2025-05-23-restoring-gold-standard-science.md"},f=Object.assign(l,{setup(c){return(d,e)=>(s(),n("div",null,[e[0]||(e[0]=i("h1",{id:"restoring-gold-standard-science",tabindex:"-1"},[o("Restoring Gold Standard Science "),i("a",{class:"header-anchor",href:"#restoring-gold-standard-science","aria-label":'Permalink to "Restoring Gold Standard Science"'},"​")],-1)),r(t),e[1]||(e[1]=a('<p>Published on Friday, May 23, 2025</p><ul><li><p><strong>Background Concerns</strong>:</p><ul><li>Trust in scientists has significantly declined over the past five years.</li><li>Majority of researchers perceive a reproducibility crisis in science, exacerbated by data falsification from leading researchers.</li><li>The Federal Government has contributed to this issue through misleading use of scientific information.</li></ul></li><li><p><strong>Examples of Misleading Scientific Practices</strong>:</p><ul><li><strong>CDC Guidance on Schools</strong>: Issued guidelines that discouraged in-person learning despite evidence supporting safer school openings.</li><li><strong>National Marine Fisheries Service</strong>: Adopted incorrect and extreme assumptions regarding North Atlantic right whale population impacting the lobster fishery.</li><li><strong>RCP 8.5 Usage</strong>: Agencies relied on an unrealistic worst-case climate change scenario, misleading public understanding of risks.</li></ul></li><li><p><strong>Commitment to Scientific Integrity</strong>:</p><ul><li>The current Administration aims to restore confidence in science through rigorous and transparent methodologies.</li><li>Emphasis on reproducibility, unbiased peer review, and transparent communication of scientific data.</li></ul></li><li><p><strong>Definition of Key Terms</strong>:</p><ul><li><strong>Employee</strong>: Defined as per 5 U.S.C. 2105.</li><li><strong>Scientific Information</strong>: Encompasses all factual data and analyses across various scientific disciplines.</li><li><strong>Scientific Misconduct</strong>: Involves fabrication, falsification, or plagiarism in research.</li></ul></li><li><p><strong>Implementation of &quot;Gold Standard Science&quot;</strong>:</p><ul><li>Agencies must develop policies to follow established principles such as transparency, collaboration, and rigorous peer review.</li><li>Specific guidance from the Office of Science and Technology Policy (OSTP) to be issued within 30 days.</li></ul></li><li><p><strong>Mandatory Rules for Agencies</strong>:</p><ul><li>Prohibition of scientific misconduct and reliance on tainted information.</li><li>Agencies required to make significant scientific data publicly available, acknowledging uncertainties in analyses.</li><li>Transparency about assumptions and adherence to quality standards in scientific evaluation.</li></ul></li><li><p><strong>Agency Policy Review</strong>:</p><ul><li>Agencies must reassess and update scientific integrity policies to conform with the new standards.</li><li>Emphasis on open exchanges of ideas and protecting dissenting viewpoints.</li></ul></li><li><p><strong>Enforcement and Compliance</strong>:</p><ul><li>Each agency must establish processes for addressing violations of scientific integrity policies.</li><li>Heads may request waivers for certain requirements for good cause.</li></ul></li><li><p><strong>Exclusions and Limitations</strong>:</p><ul><li>The order does not supersede applicable laws or alter the authority of agency heads.</li><li>No new enforceable rights are created for individuals against the government.</li></ul></li></ul><p>This executive order aims to strengthen scientific integrity within federal agencies, restore public confidence, and ensure that scientific information guides decision-making effectively and transparently.</p><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/restoring-gold-standard-science/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/restoring-gold-standard-science/</a></p>',4))]))}});export{u as __pageData,f as default};
